    Bug 1985712 - confirmation for delete/detach multiple attachments only mentions the first. r=aleca


    There is only one string replacement in that string. The argument should thus be an array of one string (an already formatted string, not an array of attachment names).

    Differential Revision: https://phabricator.services.mozilla.com/D262893

diff --git a/mail/modules/AttachmentInfo.sys.mjs b/mail/modules/AttachmentInfo.sys.mjs
index 2bfc53dc29c..cb2f63e9c51 100644
--- a/mail/modules/AttachmentInfo.sys.mjs
+++ b/mail/modules/AttachmentInfo.sys.mjs
@@ -601,10 +601,9 @@ export class AttachmentInfo {
       // Confirm to proceed.
       const message = Services.strings
         .createBundle("chrome://messenger/locale/messenger.properties")
-        .formatStringFromName(
-          "deleteAttachments",
-          attachments.map(a => a.name)
-        );
+        .formatStringFromName("deleteAttachments", [
+          attachments.map(a => a.name).join("\n"),
+        ]);
       if (!Services.prompt.confirm(null, null, message)) {
         return;
       }
@@ -694,10 +693,9 @@ export class AttachmentInfo {
       // Non-silent mode. Confirm before delete.
       const message = Services.strings
         .createBundle("chrome://messenger/locale/messenger.properties")
-        .formatStringFromName(
-          "detachAttachments",
-          attachments.map(a => a.name)
-        );
+        .formatStringFromName("detachAttachments", [
+          attachments.map(a => a.name).join("\n"),
+        ]);
       if (!Services.prompt.confirm(null, null, message)) {
         return;
       }
